where status = '0' and del_flag = '0' and tenant_id = #{tenantId}
  and (dept_id = #{deptId} or (dept_id = 0 AND NOT EXISTS (select 1 from mem_member_card_type scoped where scoped.tenant_id = mem_member_card_type.tenant_id and scoped.type_code = mem_member_card_type.type_code and scoped.dept_id = #{deptId} and scoped.del_flag = '0')))
order by min_growth asc, dept_id desc


where status = '0' and del_flag = '0' and tenant_id = #{tenantId}
  and (dept_id = #{deptId} or (dept_id = 0 AND NOT EXISTS (select 1 from mem_member_card_type scoped where scoped.tenant_id = mem_member_card_type.tenant_id and scoped.type_code = mem_member_card_type.type_code and scoped.dept_id = #{deptId} and scoped.del_flag = '0'))) and min_growth <= #{growthValue}
order by min_growth desc, dept_id desc, type_id desc
