update mem_member_card_type
type_name = #{typeName}, card_fee = #{cardFee}, discount_rate = #{discountRate}, points_rate = #{pointsRate}, min_growth = #{minGrowth}, sign_in_points = #{signInPoints}, status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where type_id = #{typeId} and tenant_id = #{tenantId} and dept_id = #{deptId}
